package com.jonaslins.curso;
import org.springframework.beans.factory.annotation.Value; import org.springframework.http.*; import org.springframework.security.authentication.*; import org.springframework.security.core.AuthenticationException; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/auth") class AuthController { private final UserRepository users; private final PasswordEncoder encoder; private final AuthenticationManager auth; private final JwtService jwt; private final String jonasEmail;
 AuthController(UserRepository u,PasswordEncoder e,AuthenticationManager a,JwtService j,@Value("${app.jonas-email}")String email){users=u;encoder=e;auth=a;jwt=j;jonasEmail=email.toLowerCase();}
 record Credentials(String email,String password,String name){} record Token(String token,String role){}
 @PostMapping("/register") ResponseEntity<?> register(@RequestBody Credentials c){if(c.email()==null||c.password()==null||c.password().length()<8)return ResponseEntity.badRequest().body("Senha deve ter ao menos 8 caracteres.");if(users.findByEmail(c.email().toLowerCase()).isPresent())return ResponseEntity.status(409).body("E-mail já cadastrado.");var role=c.email().equalsIgnoreCase(jonasEmail)?"TEACHER":"STUDENT";var u=users.save(new AppUser(c.name(),c.email(),encoder.encode(c.password()),role));return ResponseEntity.status(201).body(new Token(jwt.create(u),u.role));}
 @PostMapping("/login") ResponseEntity<?> login(@RequestBody Credentials c){try{auth.authenticate(new UsernamePasswordAuthenticationToken(c.email().toLowerCase(),c.password()));var u=users.findByEmail(c.email().toLowerCase()).orElseThrow();return ResponseEntity.ok(new Token(jwt.create(u),u.role));}catch(AuthenticationException e){return ResponseEntity.status(HttpStatus.UNAUTHORIZED).body("E-mail ou senha inválidos.");}}
}
